('aux-age:29-fd6d5407d4','aux-age',29,'Si 4x + 11 = 23, ¿cuánto vale x?','["2", "3", "5", "4"]'::jsonb,1,'Psicotécnicos','4x = 23 − 11 = 12; x = 12 / 4 = 3.',null),
